CREATE TYPE "UserRole" AS ENUM ('STUDENT', 'TEACHER', 'ADMIN');
CREATE TYPE "HomeworkStatus" AS ENUM ('TODO', 'IN_PROGRESS', 'SUBMITTED', 'GRADED');
CREATE TABLE "User" ("id" TEXT NOT NULL, "studentId" TEXT, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "name" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'STUDENT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_studentId_key" ON "User"("studentId"); CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "StudentProfile" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "className" TEXT NOT NULL, "section" TEXT, "rollNumber" TEXT, "joinedAt" TIMESTAMP(3), CONSTRAINT "StudentProfile_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "StudentProfile_userId_key" ON "StudentProfile"("userId");
CREATE TABLE "Course" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "teacherName" TEXT NOT NULL, "room" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Course_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Enrollment" ("id" TEXT NOT NULL, "studentId" TEXT NOT NULL, "courseId" TEXT NOT NULL, CONSTRAINT "Enrollment_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Enrollment_studentId_courseId_key" ON "Enrollment"("studentId", "courseId");
CREATE TABLE "Homework" ("id" TEXT NOT NULL, "courseId" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "dueDate" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Homework_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HomeworkSubmission" ("id" TEXT NOT NULL, "homeworkId" TEXT NOT NULL, "studentId" TEXT NOT NULL, "status" "HomeworkStatus" NOT NULL DEFAULT 'TODO', "progress" INTEGER NOT NULL DEFAULT 0, "score" INTEGER, "submittedAt" TIMESTAMP(3), CONSTRAINT "HomeworkSubmission_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "HomeworkSubmission_homeworkId_studentId_key" ON "HomeworkSubmission"("homeworkId", "studentId");
CREATE TABLE "Mark" ("id" TEXT NOT NULL, "studentId" TEXT NOT NULL, "subject" TEXT NOT NULL, "examName" TEXT NOT NULL, "score" DOUBLE PRECISION NOT NULL, "maxScore" DOUBLE PRECISION NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Mark_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Holiday" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "date" TIMESTAMP(3) NOT NULL, "description" TEXT);
CREATE TABLE "Session" ("sid" TEXT NOT NULL, "sess" JSONB NOT NULL, "expire" TIMESTAMP(3) NOT NULL, CONSTRAINT "Session_pkey" PRIMARY KEY ("sid")); CREATE INDEX "Session_expire_idx" ON "Session"("expire");
ALTER TABLE "StudentProfile" ADD CONSTRAINT "StudentProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Enrollment" ADD CONSTRAINT "Enrollment_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Enrollment" ADD CONSTRAINT "Enrollment_courseId_fkey" FOREIGN KEY ("courseId") REFERENCES "Course"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Homework" ADD CONSTRAINT "Homework_courseId_fkey" FOREIGN KEY ("courseId") REFERENCES "Course"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "HomeworkSubmission" ADD CONSTRAINT "HomeworkSubmission_homeworkId_fkey" FOREIGN KEY ("homeworkId") REFERENCES "Homework"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "HomeworkSubmission" ADD CONSTRAINT "HomeworkSubmission_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Mark" ADD CONSTRAINT "Mark_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
